<?php require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'POST required'],405);$data=json_decode(file_get_contents('php://input'),true) ?: $_POST;$staff=trim((string)($data['staff_id']??''));$password=(string)($data['password']??'');$s=db()->prepare('SELECT u.*,r.name role_name,s.name service_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN services s ON s.id=u.service_id WHERE u.staff_id=? AND u.status="Active"');$s->execute([$staff]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password_hash']))json_response(['success'=>false,'message'=>'Invalid credentials'],401);login_user($u);db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);audit('LOGIN','users',(int)$u['id'],'API login');json_response(['success'=>true,'message'=>'Login successful','user'=>['id'=>(int)$u['id'],'staff_id'=>$u['staff_id'],'name'=>$u['full_name'],'role'=>$u['role_name'],'service'=>$u['service_name']]]);
